<?php
declare(strict_types=1);
require_once __DIR__.'/storage.php';
function sv_ar_ingest_external_event(PDO $db,array $event): int { foreach(['source','source_id','event_type'] as $field)if(trim((string)($event[$field]??''))==='')throw new InvalidArgumentException("Missing external event field: {$field}");$payload=is_array($event['payload']??null)?$event['payload']:[];$json=sv_ar_json($payload);$hash=hash('sha256',$json);$s=$db->prepare("INSERT INTO amazon_recovery_inbox (source,source_id,event_type,amazon_order_id,safe_t_id,effective_at,payload_json,payload_hash,status) VALUES (?,?,?,?,?,?,?,?,'pending') ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id), updated_at=NOW()");$s->execute([strtolower((string)$event['source']),(string)$event['source_id'],strtoupper((string)$event['event_type']),($event['amazon_order_id']??null)?:null,($event['safe_t_id']??null)?:null,sv_ar_mysql_datetime($event['effective_at']??null),$json,$hash]);return (int)$db->lastInsertId(); }
function sv_ar_link_inbox_case(PDO $db,int $inboxId,int $caseId): bool { $link=$db->prepare('INSERT IGNORE INTO amazon_recovery_inbox_links (inbox_id,case_id) VALUES (?,?)');$ok=$link->execute([$inboxId,$caseId]);if(!$ok)return false;$mark=$db->prepare("UPDATE amazon_recovery_inbox SET status='correlated',last_error=NULL,updated_at=NOW() WHERE id=?");return $mark->execute([$inboxId]); }
function sv_ar_quarantine_inbox(PDO $db,int $inboxId,string $reason): bool { $s=$db->prepare("UPDATE amazon_recovery_inbox SET status='quarantine',last_error=?,updated_at=NOW() WHERE id=?");return $s->execute([$reason,$inboxId]); }
